def semver_sort(versions):
    def parse_version(v):
        # Split by + to separate build metadata (ignored)
        v = v.split('+')[0]

        # Split by - to separate pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            core = v
            prerelease_parts = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        return (major, minor, patch, prerelease_parts)

    def compare_prerelease(pre1, pre2):
        # None means no pre-release (sorts after pre-release)
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1

        # Compare pre-release identifiers
        for i in range(min(len(pre1), len(pre2))):
            id1, id2 = pre1[i], pre2[i]
            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                # Both numeric - compare numerically
                if int(id1) < int(id2):
                    return -1
                elif int(id1) > int(id2):
                    return 1
            elif is_digit1:
                # Numeric sorts before non-numeric
                return -1
            elif is_digit2:
                # Non-numeric sorts after numeric
                return 1
            else:
                # Both non-numeric - compare by ASCII
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer identifiers sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

    # Create list of (parsed_version, original_index, original_string)
    indexed_versions = []
    for i, v in enumerate(versions):
        parsed = parse_version(v)
        indexed_versions.append((parsed, i, v))

    # Sort by parsed version, then by original index for stability
    def sort_key(item):
        parsed, idx, _ = item
        major, minor, patch, prerelease = parsed
        # Create a sortable key: (major, minor, patch, prerelease_key, original_index)
        if prerelease is None:
            prerelease_key = (1, [])  # No pre-release sorts after
        else:
            # Convert prerelease parts to comparable form
            prerelease_key = (0, [])  # Pre-release sorts before
            for part in prerelease:
                if part.isdigit():
                    prerelease_key[1].append((0, int(part)))  # 0 prefix for numeric
                else:
                    prerelease_key[1].append((1, part))  # 1 prefix for string

        return (major, minor, patch, prerelease_key[0], prerelease_key[1], idx)

    indexed_versions.sort(key=sort_key)

    # Return sorted version strings
    return [v for _, _, v in indexed_versions]

